Tout programme Arduino a cette structure :

  void setup() { /* exécuté UNE FOIS au démarrage */ }
  void loop()  { /* exécuté EN BOUCLE indéfiniment */ }

Premier programme — clignoter la LED interne (GPIO 2 sur l'ESP-WROOM-32) :

  const int LED_PIN = 2;
  void setup() {
      Serial.begin(115200);
      pinMode(LED_PIN, OUTPUT);
      Serial.println("ESP32 demarre !");
  }
  void loop() {
      digitalWrite(LED_PIN, HIGH); Serial.println("LED ON"); delay(500);
      digitalWrite(LED_PIN, LOW);  Serial.println("LED OFF"); delay(500);
  }

Téléverse, ouvre le Moniteur Série (115200), la LED clignote.

Si le téléversement échoue avec 'Connecting...', appuie sur le bouton BOOT de l'ESP32 quand les points '....' apparaissent.

Modifie SSID et mot de passe puis téléverse :

  #include <WiFi.h>
  const char* WIFI_SSID = "NOM_DU_WIFI";
  const char* WIFI_PASSWORD = "MOT_DE_PASSE";
  void setup() {
      Serial.begin(115200); delay(500);
      WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
      int t = 0;
      while (WiFi.status() != WL_CONNECTED && t < 40) {
          delay(500); Serial.print("."); t++;
      }
      if (WiFi.status() == WL_CONNECTED) {
          Serial.print("\\nIP : "); Serial.println(WiFi.localIP());
      } else {
          Serial.println("\\nEchec Wi-Fi. Verifie SSID et mot de passe.");
      }
  }
  void loop() {}

NOTE l'adresse IP affichée — tu devras la donner au Groupe A.

ATTENTION : l'ESP32 ne fonctionne qu'en Wi-Fi 2.4 GHz (pas 5 GHz).

*** SYNCHRO 1 *** : quand ce programme fonctionne, donne ton IP au Groupe A !

  #include <WiFi.h>
  #include <WiFiUdp.h>
  const char* WIFI_SSID = "..."; const char* WIFI_PASSWORD = "...";
  WiFiUDP udp;
  char messageRecu[255];
  void setup() {
      Serial.begin(115200); delay(500);
      WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
      while (WiFi.status() != WL_CONNECTED) { delay(500); Serial.print("."); }
      Serial.print("\nIP : "); Serial.println(WiFi.localIP());
      udp.begin(4210);
      Serial.println("UDP pret");
  }
  void loop() {
      int taille = udp.parsePacket();
      if (taille > 0) {
          int n = udp.read(messageRecu, 254);
          messageRecu[n] = '\0';  // OBLIGATOIRE en C++
          Serial.print("Recu : "); Serial.println(messageRecu);
      }
  }

parsePacket() : 0 = rien, >0 = paquet dispo.
udp.read() : lit dans le tableau.
messageRecu[n] = '\\0' : termine la chaîne C++ (sinon caractères parasites).

*** SYNCHRO 2 *** : quand LED_ON/LED_OFF marchent, préviens le Groupe A !

Dans loop(), après lecture du paquet, ajoute :

  String commande = String(messageRecu);
  if (commande == "LED_ON") {
      digitalWrite(LED_PIN, HIGH);
  }
  else if (commande == "LED_OFF") {
      digitalWrite(LED_PIN, LOW);
  }
  else if (commande == "PING") {
      udp.beginPacket(udp.remoteIP(), udp.remotePort());
      udp.print("PONG");
      udp.endPacket();
  }

N'oublie pas pinMode(LED_PIN, OUTPUT) dans setup(), avec LED_PIN = 2.

Pourquoi convertir en String ? En C++, on ne peut pas comparer deux char[] avec == (ça compare les adresses mémoire, pas le contenu). Avec String, == fonctionne correctement.

Le Groupe A envoie : MOTOR:120  ou  MOTOR:120:80 (deux moteurs).

Outils C++ :
- commande.startsWith("MOTOR:") → true si commence par MOTOR:
- commande.substring(6) → texte après le 6e caractère (saute 'MOTOR:')
- valeurs.indexOf(':') → position du ':' suivant, ou -1 si absent
- texte.toInt() → conversion en entier

Ajoute dans loop() :

  else if (commande.startsWith("MOTOR:")) {
      String valeurs = commande.substring(6);
      int sep = valeurs.indexOf(':');
      if (sep > 0) {
          int g = valeurs.substring(0, sep).toInt();
          int d = valeurs.substring(sep + 1).toInt();
          Serial.print("G="); Serial.print(g);
          Serial.print(" D="); Serial.println(d);
      } else {
          Serial.print("Vitesse : "); Serial.println(valeurs.toInt());
      }
  }

Le Groupe A envoie GET_SENSOR. Le robot répond SENSOR:XXX.

L'ESP32 lit une tension analogique sur une broche (0 à 4095). On utilise GPIO 34 :
  int valeur = analogRead(34);

Ajoute dans loop() :

  else if (commande == "GET_SENSOR") {
      int valeur = analogRead(34);
      String reponse = "SENSOR:" + String(valeur);
      udp.beginPacket(udp.remoteIP(), udp.remotePort());
      udp.print(reponse);
      udp.endPacket();
      Serial.print("Capteur : "); Serial.println(valeur);
  }

Pas de capteur branché ? Pas grave : la broche flottante donne une valeur variable, suffisant pour tester la communication.

DÉFI : ajoute une commande GET_TEMP qui renvoie TEMP:XX (valeur simulée avec random(20, 31)).

*** SYNCHRO 3 *** : préviens le Groupe A pour le test final !

Firmware complet avec une fonction traiterCommande() séparée :

  #include <WiFi.h>
  #include <WiFiUdp.h>
  const char* WIFI_SSID="..."; const char* WIFI_PASSWORD="...";
  const int LED_PIN = 2;
  WiFiUDP udp; char messageRecu[255];
  void traiterCommande(String c);
  void setup() {
      Serial.begin(115200); delay(500);
      pinMode(LED_PIN, OUTPUT);
      WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
      while (WiFi.status()!=WL_CONNECTED){delay(500);Serial.print(".");}
      Serial.print("\nIP: "); Serial.println(WiFi.localIP());
      udp.begin(4210);
  }
  void loop() {
      if (udp.parsePacket()>0) {
          int n=udp.read(messageRecu,254); messageRecu[n]='\\0';
          traiterCommande(String(messageRecu));
      }
  }
  void traiterCommande(String c) {
      if (c=="PING"){udp.beginPacket(udp.remoteIP(),udp.remotePort());udp.print("PONG");udp.endPacket();}
      else if (c=="LED_ON")  digitalWrite(LED_PIN,HIGH);
      else if (c=="LED_OFF") digitalWrite(LED_PIN,LOW);
      else if (c.startsWith("MOTOR:")) { /* voir B-05 */ }
      else if (c=="GET_SENSOR") { /* voir B-06 */ }
  }

Pourquoi une fonction séparée ? loop() reste courte, et ajouter une commande = ajouter un 'else if' dans traiterCommande().
